import{_ as t,o as i,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"CDS G/H (Day 1) - OSD: Scrub/SnapTrim IO Prioritization","description":"","frontmatter":{"title":"CDS G/H (Day 1) - OSD: Scrub/SnapTrim IO Prioritization","date":"2014-06-24T00:00:00.000Z","updated":"2014-06-25T00:00:00.000Z","tags":["Ceph","OSD","IO优先级","Scrub","SnapTrim"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.md","filePath":"posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.md","lastUpdated":1780459816000}'),n={name:"posts/2014/CDS_G_H_Day_1_-_OSD_-_Scrub_SnapTrim_IO_Prioritization.md"};function _(a,r,l,p,e,S){return i(),o("div",null,[...r[0]||(r[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 下午</p><p><strong>会议主题</strong>： OSD操作优化讨论，重点为scrub、snap trim和IO优先级调整。</p><p><strong>参会人员</strong>： Sam（主持人）、其他研发人员</p><p><strong>会议内容</strong>：</p><p><strong>1. scrub、snap trim IO优先级讨论</strong></p><ul><li><strong>问题</strong>： 现有后台IO密集型任务（如scrub、snap trim）影响客户端IO，需调整优先级。</li><li><strong>解决方案</strong>： <ul><li>分配独立线程池，减少线程数量。</li><li>使用内核IO优先级机制降低线程优先级。</li><li>封装任务为工作项，放入OSD操作队列（OSD oport Q），利用令牌桶机制平衡恢复请求与客户端请求。</li><li>考虑将所有工作项统一放入操作队列，确定每个工作项的成本和优先级。</li></ul></li></ul><p><strong>2. 操作队列（oper Q）与工作项</strong></p><ul><li><strong>操作队列</strong>： 处理scrub、snap trim等操作请求。</li><li><strong>工作项</strong>： 封装任务为工作项，放入操作队列。</li><li><strong>优先级</strong>： 操作队列根据优先级和成本处理工作项，优先级高于63的工作项使用严格优先级队列，低于63的工作项按成本动态调整。</li></ul><p><strong>3. PG移除</strong></p><ul><li>PG移除操作保留在现有线程池中，设置较低优先级。</li></ul><p><strong>4. IO优先级</strong></p><ul><li>结合操作队列，实现更精细的IO优先级控制。</li><li>对于scrub操作，调整锁的获取和释放之间的优先级。</li></ul><p><strong>5. 后续行动计划</strong></p><ul><li>完善scrub、snap trim等任务的优先级和成本设置。</li><li>考虑将所有工作项统一放入操作队列中。</li><li>对PG移除操作进行优先级调整。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议讨论了OSD操作的优化议题，提出了改进方案，并制定了后续行动计划。通过优化操作队列和IO优先级，可以提高Ceph系统的性能和稳定性。</p>',17)])])}const c=t(n,[["render",_]]);export{g as __pageData,c as default};
